SourceCode.Declaration:
/// <summary>
/// Copy sales order guide
/// </summary>
class METSalesOrderGuideCopy
{
    METSalesOrderGuideTable         orderGuide;
    METSalesOrderGuideCopyMode      copyMode;

}

Method.Source:
    public void run()
    {
        METSalesOrderGuideTable newOrderGuide;
        METSalesOrderGuideLine  line, newLine;

        ttsbegin;

        newOrderGuide.initValue();        
        newOrderGuide.Description       = orderGuide.Description;

        switch(copyMode)
        {
            case METSalesOrderGuideCopyMode::NewGuide:
                newOrderGuide.SalesOrderGuideID  = METSalesOrderGuideTable::nextOrderGuideID();
                break;

            case METSalesOrderGuideCopyMode::NewVersion:
                newOrderGuide.VersionNum            = orderGuide.VersionNum + 1;
                newOrderGuide.BaseGuideID           = orderGuide.BaseGuideID;
                newOrderGuide.SalesOrderGuideID     = orderGuide.SalesOrderGuideID;
                newOrderGuide.IsLatestVersion       = true;
                int dashIndex = strFind(newOrderGuide.SalesOrderGuideID, '-', 999, -999);
                if(dashIndex)
                {
                    newOrderGuide.SalesOrderGuideID = subStr(newOrderGuide.SalesOrderGuideID, 1, dashIndex - 1);
                }
                newOrderGuide.SalesOrderGuideID += strFmt('-%1', newOrderGuide.VersionNum);
                break;

            default:
                throw error(strFmt("Unknown value '%1' for %2 in %3",
                    copyMode,
                    identifierStr(copyMode),
                    funcName()));

        }

        newOrderGuide.insert();

        RecordInsertList newLineList = new RecordInsertList(tableNum(METSalesOrderGuideLine));

        while select line
            where   line.SalesOrderGuideID    == orderGuide.SalesOrderGuideID
        {
            newLine.clear();
            newLine.data(line);
            newLine.SalesOrderGuideID = newOrderGuide.SalesOrderGuideID;

            newLineList.add(newLine);            
        }
        newLineList.insertDatabase();

        if(newOrderGuide.VersionNum > 0)
        {
            this.clearLatestVersionFlag(newOrderGuide);
        }

        ttscommit;

        info(strFmt("Order guide %1 created as a copy of %2", 
            newOrderGuide.SalesOrderGuideID, 
            orderGuide.SalesOrderGuideID));
    }

/// <summary>
/// If a new version has been created via a copy, clear the 'latest version' flag
/// on previous guides.
/// </summary>
/// <param name = "_newlyCreatedGuide"></param>
protected void clearLatestVersionFlag(METSalesOrderGuideTable _newlyCreatedGuide)
{
    METSalesOrderGuideTable supersededGuide;
    update_recordset supersededGuide
        setting IsLatestVersion = false
        where   supersededGuide.BaseGuideID == _newlyCreatedGuide.BaseGuideID
        &&      supersededGuide.VersionNum  <  _newlyCreatedGuide.VersionNum;
}

/// <summary>
/// Get/set copy mode (new guide or new version).
/// </summary>
/// <param name = "_copyMode">_copyMode</param>
/// <returns>copyMode</returns>
METSalesOrderGuideCopyMode parmCopyMode(METSalesOrderGuideCopyMode _copyMode = copyMode)
{
    copyMode = _copyMode;
    return copyMode;
}

/// <summary>
/// Get/set originating order guide
/// </summary>
/// <param name = "_orderGuide">_orderGuide</param>
/// <returns>orderGuide</returns>
METSalesOrderGuideTable parmOrderGuide(METSalesOrderGuideTable _orderGuide = orderGuide)
{
    orderGuide = _orderGuide;
    return orderGuide;
}

public static METSalesOrderGuideCopy construct()
{
    return new METSalesOrderGuideCopy();            
}

    public static void main(Args _args)
    {
        METSalesOrderGuideCopy  copy = METSalesOrderGuideCopy::construct();
        METSalesOrderGuideTable orderGuide = _args.record();

        if(!orderGuide)
        {
            throw error(error::missingRecord(funcName()));
        }
        if(_args.parmEnumType() != enumNum(METSalesOrderGuideCopyMode))
        {
            throw error(error::missingParameter(null));
        }
        if(Box::yesNo(strFmt("Copy order guide '%1'?", orderGuide.SalesOrderGuideID), DialogButton::No) == DialogButton::Yes)
        {
            copy.parmOrderGuide(orderGuide);
            copy.parmCopyMode(_args.parmEnum());
            copy.run();

            if(orderGuide.dataSource())
            {
                orderGuide.dataSource().research();
            }
        }
    }
